using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Media;using System.Text;using System.Windows.Forms;
namespace SlopStudio {
 internal sealed class FallingRegion {public RectangleF Bounds;public string Name;public Color Color;public float Velocity,Horizontal,Angle,Spin;}
 internal sealed class MayhemOverlay:Control {
  private Bitmap _background;private List<FallingRegion> _regions;private Timer _timer;private Stopwatch _watch=new Stopwatch();private double _last;private SoundPlayer _sound;private MemoryStream _wave;
  public MayhemOverlay(Bitmap background,List<FallingRegion> regions){_background=background;_regions=regions;Dock=DockStyle.Fill;DoubleBuffered=true;TabStop=true;var random=new Random(20261028);using(var g=Graphics.FromImage(background))foreach(var r in regions){using(var b=new SolidBrush(Color.FromArgb(44,46,45)))g.FillRectangle(b,r.Bounds.X-1,r.Bounds.Y-1,r.Bounds.Width+2,r.Bounds.Height+2);r.Horizontal=(float)(random.NextDouble()-.5)*90;r.Spin=(float)(random.NextDouble()-.5)*40;r.Velocity=-40-random.Next(200);}_timer=new Timer{Interval=16};_timer.Tick+=delegate{double now=_watch.Elapsed.TotalSeconds,dt=Math.Min(.05,now-_last);_last=now;foreach(var r in _regions){r.Velocity+=(float)(1100*dt);r.Bounds=new RectangleF(r.Bounds.X+(float)(r.Horizontal*dt),r.Bounds.Y+(float)(r.Velocity*dt),r.Bounds.Width,r.Bounds.Height);r.Angle+=(float)(r.Spin*dt);if(r.Bounds.Y+r.Bounds.Height>Height&&r.Velocity>0){r.Bounds=new RectangleF(r.Bounds.X,Height-r.Bounds.Height,r.Bounds.Width,r.Bounds.Height);r.Velocity*=-.55f;}}Invalidate();};_watch.Start();_timer.Start();PlayExplosion();}
  private void PlayExplosion(){try{_wave=new MemoryStream();var w=new BinaryWriter(_wave,Encoding.ASCII,true);const int rate=48000,frames=28800;w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write(36+frames*2);w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(Encoding.ASCII.GetBytes("data"));w.Write(frames*2);var random=new Random(71);double low=0;for(int i=0;i<frames;i++){double t=i/(double)rate;low=.86*low+.14*(random.NextDouble()*2-1);double sample=(.65*low+.35*Math.Sin(2*Math.PI*(90*t-35*t*t)))*.22*Math.Exp(-t*8)*Math.Min(1,t*1000);w.Write((short)(sample*32767));}w.Flush();_wave.Position=0;_sound=new SoundPlayer(_wave);_sound.Play();}catch(Exception ex){ErrorLog.Write("Mayhem sound",ex);}}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.DrawImageUnscaled(_background,0,0);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;foreach(var region in _regions){var state=e.Graphics.Save();e.Graphics.TranslateTransform(region.Bounds.X+region.Bounds.Width/2,region.Bounds.Y+region.Bounds.Height/2);e.Graphics.RotateTransform(region.Angle);var rect=new Rectangle((int)(-region.Bounds.Width/2),(int)(-region.Bounds.Height/2),Math.Max(1,(int)region.Bounds.Width),Math.Max(1,(int)region.Bounds.Height));using(var b=new SolidBrush(region.Color))e.Graphics.FillRectangle(b,rect);StudioDraw.Label(e.Graphics,region.Name,Font,rect,Color.WhiteSmoke,TextFormatFlags.VerticalCenter);e.Graphics.Restore(state);}float x=(float)(Math.Sin(_watch.Elapsed.TotalSeconds*2.7)*Width*.12),y=(float)(Math.Cos(_watch.Elapsed.TotalSeconds*3.4)*Height*.18);using(var font=new Font("Segoe UI",Math.Max(22,Width/38),FontStyle.Bold))using(var brush=new SolidBrush(Color.FromArgb(240,245,190,39)))using(var format=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center})e.Graphics.DrawString("Donaudampfschiffahrtselektrizitätenhauptbetriebswerkbauunterbeamtengesellschaft",font,brush,new RectangleF(x+20,y+Height*.1f,Width-40,Height*.7f),format);using(var b=new SolidBrush(Color.FromArgb(210,25,27,31)))e.Graphics.FillRectangle(b,0,Height-38,Width,38);StudioDraw.Label(e.Graphics,"Space · Restore project view",Font,new Rectangle(10,Height-36,Width-20,32),Color.WhiteSmoke,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
  protected override void Dispose(bool disposing){if(disposing){_timer.Stop();_timer.Dispose();_background.Dispose();if(_sound!=null){_sound.Stop();_sound.Dispose();}if(_wave!=null)_wave.Dispose();}base.Dispose(disposing);}
 }
 public sealed partial class MainForm {
  private MayhemOverlay _mayhem;
  internal void StartMayhem(){if(_mayhem!=null||_recording)return;_mayhem=_timeline.CreateMayhemOverlay();_timeline.Controls.Add(_mayhem);_mayhem.BringToFront();_mayhem.Focus();}
  private void StopMayhem(){if(_mayhem==null)return;_timeline.Controls.Remove(_mayhem);_mayhem.Dispose();_mayhem=null;_timeline.Focus();}
 }
}
